Put your final answer within \boxed{}.

#include <iostream>
#include <vector>
#include <cmath>

using namespace std;

int main() {
    // Define the coefficients of the polynomials
    vector<int> poly1 = {7, -3, g};
    vector<int> poly2 = {3, h, -8};

    // Calculate the product of the polynomials
    vector<int> product = multiplyPolynomials(poly1, poly2);

    // Check if the product is equal to the given expression
    if (product == {21, -44, -35, 14, -16}) {
        // Calculate the sum of g and h
        int g = poly1[2];
        int h = poly2[1];
        int sum = g + h;

        // Print the sum
        cout << "The sum of g and h is: " << sum << endl;
    } else {
        cout << "The product of the polynomials does not match the given expression." << endl;
    }

    return 0;
}

vector<int> multiplyPolynomials(vector<int> poly1, vector<int> poly2) {
    int degree = poly1.size() + poly2.size() - 1;
    vector<int> product(degree, 0);

    for (int i = 0; i < poly1.size(); i++) {
        for (int j = 0; j < poly2.size(); j++) {
            product[i + j] += poly1[i] * poly2[j];
        }
    }

    return product;
}

