#include <iostream>
#include <cmath>
using namespace std;

double f(double x) {
    return x * x * x - 3 * x + 2;
}

double df(double x) {
    return 3 * x * x - 3;
}

double find_root(double a, double b, double tol) {
    double x = (a + b) / 2;
    while (fabs(f(x)) > tol) {
        if (f(a) * f(x) < 0) {
            b = x;
        } else {
            a = x;
        }
        x = (a + b) / 2;
    }
    return x;
}

int main() {
    double x1, x2, x3, y1, y2, y3;
    double tol = 1e-6;

    // Find the roots of the equation x^3 - 3x + 2 = 0
    x1 = find_root(0, 1, tol);
    x2 = find_root(1, 2, tol);
    x3 = find_root(2, 3, tol);

    // Find the corresponding y-values
    y1 = f(x1);
    y2 = f(x2);
    y3 = f(x3);

    // Compute the sum of the x-values and y-values
    double sum_x = x1 + x2 + x3;
    double sum_y = y1 + y2 + y3;

    // Output the result
    cout << "The ordered pair is (" << sum_x << ", " << sum_y << ").";
}

